function formatEmailFrom(from) {
  if (!from) return 'Unknown sender';
  if (typeof from === 'string') return from;
  if (from.text) return from.text;
  if (Array.isArray(from.value) && from.value[0]) {
    const v = from.value[0];
    if (v.name && v.address) return `${v.name} <${v.address}>`;
    return v.address || v.name || 'Unknown sender';
  }
  return 'Unknown sender';
}

function looksLikeUuidName(name) {
  if (!name) return true;
  const compact = String(name).replace(/[\s-]/g, '');
  return /^[0-9a-f]{32}$/i.test(compact);
}

function candidateFromFileName(fileName) {
  if (!fileName) return null;
  const cleaned = fileName
    .replace(/\.(pdf|docx?|PDF|DOCX?)$/,'')
    .replace(/[-_]+/g, ' ')
    .replace(/\bresume\b/gi, '')
    .replace(/\bcv\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned || looksLikeUuidName(cleaned)) return null;
  return cleaned;
}

const items = [];
for (const item of $input.all()) {
  const binary = item.binary || {};
  for (const key of Object.keys(binary)) {
    if (!key.startsWith('attachment_')) continue;
    const file = binary[key];
    const lowerName = (file.fileName || key).toLowerCase();
    const mime = (file.mimeType || '').toLowerCase();
    const isResume =
      lowerName.endsWith('.pdf') ||
      lowerName.endsWith('.docx') ||
      lowerName.endsWith('.doc') ||
      mime.includes('pdf') ||
      mime.includes('word') ||
      mime.includes('document');
    if (!isResume) continue;
    const fileName = file.fileName || key;
    items.push({
      json: {
        emailSubject: item.json.subject || '(no subject)',
        emailFrom: formatEmailFrom(item.json.from || item.json.From),
        fileName,
        candidateName: candidateFromFileName(fileName),
      },
      binary: { data: file },
    });
  }
}
return items;

const token = $('Login HireFlow API').first().json.access_token;
if (!token) throw new Error('Login failed — no access_token');
return $('Extract Resume Attachments').all().map((item) => ({
  json: { ...item.json, access_token: token },
  binary: item.binary,
}));

function looksLikeUuidName(name) {
  if (!name) return true;
  const compact = String(name).replace(/[\s-]/g, '');
  return /^[0-9a-f]{32}$/i.test(compact);
}

const data = $input.first().json || {};
if (!data.ok) {
  throw new Error(data.error || data.detail?.error || 'Visible RPA failed');
}
if (!data.best_job_title || !data.best_score) {
  throw new Error(data.message || 'Match score missing — not sending success Slack');
}

// RPA returns one best job only. Do not notify HR unless that best score is ≥60%.
const numericScore = Number(String(data.best_score).replace(/[^0-9.]/g, ''));
if (!Number.isFinite(numericScore)) {
  throw new Error(`Invalid best-match score: ${data.best_score}`);
}
if (numericScore < 60) {
  // Returning no items ends the success branch silently: no Slack message is sent.
  return [];
}

const meta = $('Extract Resume Attachments').first().json;
const token = $('Attach Token + Resume').first().json.access_token;

const rawName = data.candidate_name || meta.candidateName || '';
const candidate = looksLikeUuidName(rawName) ? 'Unknown Candidate' : String(rawName).trim();
const best = data.best_job_title;
const company = data.company || 'N/A';
const score = data.best_score;

const text = [
  `<!channel>`,
  ``,
  `👋 *Dear HR Team,*`,
  ``,
  `A new candidate resume just landed in HireFlow and has been screened against our open roles.`,
  ``,
  `*Candidate:* ${candidate}`,
  `*Resume file:* ${data.resume_filename || meta.fileName || 'N/A'}`,
  `*Received from:* ${meta.emailFrom || data.email_from || 'N/A'}`,
  `*Email subject:* ${meta.emailSubject || data.email_subject || '(no subject)'}`,
  ``,
  `*Best matched job*`,
  `• *${best}* @ ${company}`,
  `  Match score: *${score}*`,
  `_Other open roles were also assessed; only the highest match is shown._`,
  ``,
  `_Please review this candidate and proceed with shortlisting if it looks like a fit._`,
].join('\n');

return [{ json: { text, access_token: token, ...data, candidate_name: candidate } }];

function pickError(raw) {
  if (raw == null) return 'Unknown error';
  if (typeof raw === 'string') return raw;
  if (typeof raw === 'number' || typeof raw === 'boolean') return String(raw);

  // FastAPI HTTPException body: { detail: { error, trace } } or { detail: "..." }
  const detail = raw.detail;
  if (typeof detail === 'string') return detail;
  if (detail && typeof detail === 'object') {
    if (detail.error) return String(detail.error);
    try { return JSON.stringify(detail); } catch { /* ignore */ }
  }

  const nested =
    raw.error?.description ||
    raw.error?.message ||
    raw.message ||
    raw.description ||
    raw.statusMessage ||
    null;
  if (typeof nested === 'string') {
    try {
      const parsed = JSON.parse(nested);
      if (parsed?.detail?.error) return String(parsed.detail.error);
      if (typeof parsed?.detail === 'string') return parsed.detail;
    } catch { /* plain text */ }
    return nested;
  }

  try {
    return JSON.stringify(raw);
  } catch {
    return String(raw);
  }
}

const err = $input.first().json || {};
const node =
  err.node?.name ||
  err.node ||
  err.name ||
  'Open Browser + Run HireFlow';

const msg = pickError(err);
const token = (() => {
  try { return $('Attach Token + Resume').first().json.access_token; } catch { return null; }
})();

const text = [
  `<!channel>`,
  ``,
  `🚨 *HireFlow Automation Failed*`,
  ``,
  `*Node:* ${node}`,
  `*Error:* ${msg}`,
  `*Time:* ${new Date().toISOString()}`,
  ``,
  `_Open n8n → Executions → open this run → click failed node._`,
].join('\n');

return [{ json: { text, node, error: msg, access_token: token } }];
